import{c as r,Q as d,j as e,m as a}from"./chunks/framework.rWdQudnF.js";const c=JSON.parse('{"title":"系统设计","description":"","frontmatter":{"title":"系统设计"},"headers":[],"relativePath":"综合知识/软件工程/系统设计.md","filePath":"综合知识/软件工程/系统设计.md","lastUpdated":null}'),n={name:"综合知识/软件工程/系统设计.md"};function l(o,t,s,i,h,g){return d(),e("div",null,[...t[0]||(t[0]=[a('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] 逆向工程（4 个级别/重构/设计恢复/再工程/正向工程）</li><li>[x] 处理流程设计（PFD/IPO/N-S 图/PAD/BPR/BPM）</li><li>[x] 系统设计（概要设计/详细设计/基本原理/设计原则）</li><li>[x] 模块化设计（内聚 7 级/耦合 7 级）</li><li>[x] 人机界面设计（三大黄金原则）</li><li>[x] 结构化设计工具</li><li>[x] 系统运行与维护（遗留系统/系统转换/维护类型）</li><li>[x] 软件文档分类</li><li>[x] 系统转换方式（直接/并行/分段/渐进式）</li><li>[x] 维护类型辨析（改正性/适应性/完善性/预防性）</li><li>[x] 遗留系统处置补充</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="处理流程设计" tabindex="-1">处理流程设计 <a class="header-anchor" href="#处理流程设计" aria-label="Permalink to &quot;处理流程设计&quot;">​</a></h3><p><strong>BPR（业务流程重组）vs BPM（业务流程管理）：</strong></p><table tabindex="0"><thead><tr><th>对比</th><th>BPR</th><th>BPM</th></tr></thead><tbody><tr><td>核心</td><td>对所有流程进行再造</td><td><strong>不要求对所有流程再造</strong>，根据现有流程规范化设计</td></tr><tr><td>层面</td><td>彻底重构</td><td>三个层面：<strong>规范流程、优化流程、再造流程</strong></td></tr></tbody></table><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260517221346.png" alt="image.png"></p><hr><h3 id="系统设计" tabindex="-1">系统设计 <a class="header-anchor" href="#系统设计" aria-label="Permalink to &quot;系统设计&quot;">​</a></h3><p>系统设计主要目的：为系统制定蓝图，在各种技术和实施方法中权衡利弊，精心设计，合理地使用各种资源，最终勾画出新系统的详细设计方法。</p><p>系统设计方法：结构化设计方法，面向对象设计方法。</p><p>系统设计的主要内容：概要设计、详细设计。</p><p>概要设计基本任务：又称为系统总体结构设计，是将系统的功能需求分配给软件模块，确定每个模块的功能和调用关系，形成软件的模块结构图，即系统结构图。</p><p>详细设计的基本任务：模块内详细算法设计、模块内数据结构设计、数据库的物理设计、其他设计（代码、输入/输出格式、用户界面）、编写详细设计说明书、评审。</p><hr><blockquote><p>系统设计目的：为系统制定蓝图，勾画新系统的详细设计方案。</p></blockquote><p><strong>主要内容：</strong></p><ul><li><strong>概要设计</strong>（系统总体结构设计）：功能需求分配给模块，确定模块功能和调用关系 → <strong>模块结构图（系统结构图）</strong></li><li><strong>详细设计</strong>：模块内算法设计、数据结构设计、数据库物理设计、代码/输入输出/界面设计、编写详细设计说明书、评审</li></ul><p><strong>基本原理：</strong></p><table tabindex="0"><thead><tr><th>原理</th><th>说明</th></tr></thead><tbody><tr><td><strong>抽象化</strong></td><td>忽略细节，关注本质</td></tr><tr><td><strong>自顶向下，逐步求精</strong></td><td>从高层到低层逐步细化</td></tr><tr><td><strong>信息隐蔽</strong></td><td>模块内部信息对外不可见</td></tr><tr><td><strong>模块独立</strong></td><td>高内聚、低耦合</td></tr></tbody></table><p><strong>设计原则：</strong> 模块大小适中、减少调用深度、多扇入少扇出、单入口单出口、模块作用域在模块内、功能可预测。</p><h4 id="内聚性-从低→高" tabindex="-1">内聚性（从低→高） <a class="header-anchor" href="#内聚性-从低→高" aria-label="Permalink to &quot;内聚性（从低→高）&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:center;">级别</th><th>说明</th></tr></thead><tbody><tr><td style="text-align:center;">偶然内聚</td><td>模块内各成分无实质关系</td></tr><tr><td style="text-align:center;">逻辑内聚</td><td>逻辑上相似但功能不同</td></tr><tr><td style="text-align:center;">时间内聚</td><td>同一时间执行（如初始化）</td></tr><tr><td style="text-align:center;">过程内聚</td><td>按特定次序执行</td></tr><tr><td style="text-align:center;">通信内聚</td><td>操作同一数据</td></tr><tr><td style="text-align:center;">顺序内聚</td><td>一个成分的输出是另一个的输入</td></tr><tr><td style="text-align:center;"><strong>功能内聚</strong></td><td>所有成分共同完成单一功能，<strong>最强</strong></td></tr></tbody></table><h4 id="耦合性-从低→高" tabindex="-1">耦合性（从低→高） <a class="header-anchor" href="#耦合性-从低→高" aria-label="Permalink to &quot;耦合性（从低→高）&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:center;">级别</th><th>说明</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>无直接耦合</strong></td><td>模块间无直接关系，<strong>最弱</strong></td></tr><tr><td style="text-align:center;">数据耦合</td><td>通过简单数据参数交换</td></tr><tr><td style="text-align:center;">标记耦合</td><td>通过数据结构传递</td></tr><tr><td style="text-align:center;">控制耦合</td><td>传递控制信息影响执行路径</td></tr><tr><td style="text-align:center;">外部耦合</td><td>与外部环境绑定</td></tr><tr><td style="text-align:center;">公共耦合</td><td>共享全局数据</td></tr><tr><td style="text-align:center;">内容耦合</td><td>直接访问另一模块内部数据，<strong>最强</strong></td></tr></tbody></table><p>系统结构图(SC)又称为模块结构图，它是软件概要设计阶段的工具，反映系统的功能实现和模块之间的联系与通信，包括各模块之间的层次结构，即反映了系统的总体结构。</p><h4 id="流程表示工具-★" tabindex="-1">流程表示工具 ★ <a class="header-anchor" href="#流程表示工具-★" aria-label="Permalink to &quot;流程表示工具 ★&quot;">​</a></h4><table tabindex="0"><thead><tr><th>工具</th><th>特点</th></tr></thead><tbody><tr><td><strong>程序流程图（PFD）</strong></td><td>图框表示操作，独立于语言，由顺序/选择/循环组成</td></tr><tr><td><strong>IPO 图</strong></td><td>描述每个模块的输入、输出和数据加工</td></tr><tr><td><strong>N-S 图（盒图）</strong></td><td>容易表示嵌套和层次关系，结构化强，<strong>不适合复杂程序</strong></td></tr><tr><td><strong>问题分析图（PAD）</strong></td><td>支持结构化程序设计，引导使用结构化方法，逻辑清晰</td></tr></tbody></table><p>详细设计的表示工具有图形工具、表格工具和语言工具。其中图形工具有业务流图、程序流程图、PAD图、NS流程图。</p><ul><li>程序流程图又称为程序框图，是使用最广泛然的一种描述程序逻辑结构的工具。它用方框表示一个处理步骤，菱形表示一个逻辑条件，箭头表示控制流向。其优点是：结构清晰，易于理解，易于修改。缺点是：只能描述执行过程而不能描述有关的数据。</li><li>NS流程图，也称为盒图，是一种强制使用结构化构造的图示工具，也称为方框图。其具有以下特点：功能域明确、不可能任意转移控制、很容易确定局部和全局数据的作用域、很容易表示嵌套关系及模板的层次关系。</li><li>PAD图是一种改进的图形描述方式，可以用来取代程序流程图，相比程序流程图更直观，结构更清晰。最大的优点是能够反映和描述自顶向下的历史和过程。PAD提供了5种基本控制结构的图示，并允许递归使用。</li></ul><hr><h3 id="人机界面设计" tabindex="-1">人机界面设计 <a class="header-anchor" href="#人机界面设计" aria-label="Permalink to &quot;人机界面设计&quot;">​</a></h3><p><strong>三大黄金原则：</strong></p><ol><li><strong>置用户于控制之下</strong></li><li><strong>减少用户的记忆负担</strong></li><li><strong>保持界面的一致性</strong></li></ol><hr><h3 id="五、结构化设计工具" tabindex="-1">五、结构化设计工具 <a class="header-anchor" href="#五、结构化设计工具" aria-label="Permalink to &quot;五、结构化设计工具&quot;">​</a></h3><table tabindex="0"><thead><tr><th>工具</th><th>适用范围</th></tr></thead><tbody><tr><td>盒图、HIPO 图、程序流程图</td><td>结构化设计</td></tr><tr><td><strong>顺序图</strong>（Sequence Diagram）</td><td><strong>面向对象设计（UML）</strong>，不属于结构化设计工具</td></tr></tbody></table><hr><p>？？ 这部分哪里的内容</p><p><strong>软件系统文档分类：</strong></p><ul><li><strong>用户文档</strong>：描述系统功能和使用方法，不涉及实现细节</li><li><strong>系统文档</strong>：描述系统设计、实现和测试等详细内容</li></ul><hr><hr><h3 id="九、遗留系统补充" tabindex="-1">九、遗留系统补充 <a class="header-anchor" href="#九、遗留系统补充" aria-label="Permalink to &quot;九、遗留系统补充&quot;">​</a></h3><blockquote><p>遗留系统特征：维护工作变得越来越困难。处置策略复用已有判断。</p></blockquote><table tabindex="0"><thead><tr><th style="text-align:left;">策略</th><th>条件</th><th>记忆</th></tr></thead><tbody><tr><td style="text-align:left;">淘汰</td><td>低业务价值 + 低质量</td><td></td></tr><tr><td style="text-align:left;"><strong>继承</strong></td><td><strong>高业务价值 + 低质量</strong></td><td>业务紧依赖</td></tr><tr><td style="text-align:left;">改造</td><td>高业务价值 + 高质量</td><td></td></tr><tr><td style="text-align:left;"><strong>集成</strong></td><td>低业务价值 + 高质量</td><td>技术含量较高</td></tr></tbody></table><blockquote><p>⚠️ 高频考点：技术含量较高、业务价值较低 → <strong>集成</strong>策略；业务价值高、技术落后 → <strong>继承</strong>策略。</p></blockquote><hr><h3 id="十、软件设计活动" tabindex="-1">十、软件设计活动 <a class="header-anchor" href="#十、软件设计活动" aria-label="Permalink to &quot;十、软件设计活动&quot;">​</a></h3><table tabindex="0"><thead><tr><th>活动</th><th>内容</th></tr></thead><tbody><tr><td><strong>数据设计</strong></td><td>定义数据结构和数据库模式</td></tr><tr><td><strong>架构设计</strong></td><td>确定系统高层结构和组件</td></tr><tr><td><strong>人机界面设计</strong></td><td>设计用户界面和交互方式</td></tr><tr><td><strong>过程设计</strong></td><td>定义业务逻辑和工作流程</td></tr></tbody></table>',50)])])}const x=r(n,[["render",l]]);export{c as __pageData,x as default};
